# The risk score formula is:
# (age/100 * 30)
# + (total_conditions * 5 * 0.25)
# + (avg_severity * 10 * 0.25)
# + (20 if recent records have abnormal vitals else 0)
# Answer is always between 0.0 and 100.0.

def test_patient_risk_score():

    # Test 1: Young patient, no conditions, no severity, normal vitals
    patients = {'p1': MockPatient(age=20, conditions=0, severity=0.0)}
    recent_records_dict = {'p1':[normal_record(), normal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # Calculation: (20/100)*30 = 6, 0, 0, 0 = 6
    assert abs(patient_risk_score(hospital, 'p1') - 6.0) < 1e-7, "Low risk, young, healthy, normal vitals"

    # Test 2: Old patient, 3 conditions, avg severity 2.0, has abnormal vitals
    patients = {'p2': MockPatient(age=80, conditions=3, severity=2.0)}
    recent_records_dict = {'p2':[abnormal_record(), normal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # (80/100)*30=24, 3*5*0.25=3.75, 2.0*10*0.25=5, +20 (abnormal) => 24+3.75+5+20=52.75
    assert abs(patient_risk_score(hospital, 'p2') - 52.75) < 1e-7, "Old, 3 conditions, severity 2.0, abnormal"

    # Test 3: Middle age, 5 conditions, severity 5, all records normal
    patients = {'p3': MockPatient(age=50, conditions=5, severity=5.0)}
    recent_records_dict = {'p3':[normal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # (50/100)*30=15, 5*5*0.25=6.25, 5.0*10*0.25=12.5, +0
    # 15+6.25+12.5=33.75
    assert abs(patient_risk_score(hospital, 'p3') - 33.75) < 1e-7, "Mid-age, 5 conditions, severity 5, no abnormal"

    # Test 4: All zeros, no records (should not be abnormal)
    patients = {'p4': MockPatient(age=0, conditions=0, severity=0.0)}
    recent_records_dict = {}  # patient 'p4' not present
    hospital = MockHospital(patients, recent_records_dict)
    # (0/100)*30=0, 0, 0, +0
    assert abs(patient_risk_score(hospital, 'p4') - 0.0) < 1e-7, "All zero, no records"

    # Test 5: High risk caps at 100
    # Compose values that would otherwise exceed 100
    patients = {'p5': MockPatient(age=100, conditions=12, severity=10.0)}
    recent_records_dict = {'p5':[abnormal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # (100/100)*30=30, 12*5*0.25=15, 10*10*0.25=25, +20=30+15+25+20=90
    assert abs(patient_risk_score(hospital, 'p5') - 90.0) < 1e-7, "Max values, capped below 100"

    # Test 6: Minimal input, no conditions, no severity, record abnormal
    patients = {'p6': MockPatient(age=1, conditions=0, severity=0.0)}
    recent_records_dict = {'p6':[abnormal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # (1/100)*30=0.3, 0, 0, +20=20.3
    assert abs(patient_risk_score(hospital, 'p6') - 20.3) < 1e-7, "Young, abnormal record"

    # Test 7: Negative age (invalid?), no conditions, no severity, no abnormal
    patients = {'p7': MockPatient(age=-10, conditions=0, severity=0.0)}
    recent_records_dict = {'p7':[normal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # (-10/100)*30=-3, 0, 0, +0=-3
    assert abs(patient_risk_score(hospital, 'p7') - (-3.0)) < 1e-7, "Negative age"

    # Test 8: Recent records empty list, should count as no abnormal
    patients = {'p8': MockPatient(age=40, conditions=2, severity=3.0)}
    recent_records_dict = {'p8':[]}
    hospital = MockHospital(patients, recent_records_dict)
    # (40/100)*30=12, 2*5*0.25=2.5, 3*10*0.25=7.5
    # 12+2.5+7.5=22.0
    assert abs(patient_risk_score(hospital, 'p8') - 22.0) < 1e-7, "Empty records list is not abnormal"

    # Test 9: Recent records, mixture but at least one abnormal
    patients = {'p9': MockPatient(age=30, conditions=3, severity=5.0)}
    recent_records_dict = {'p9':[normal_record(), abnormal_record(), normal_record()]}
    hospital = MockHospital(patients, recent_records_dict)
    # (30/100)*30=9, 3.75, 12.5, +20 = 9+3.75+12.5+20=45.25
    assert abs(patient_risk_score(hospital, 'p9') - 45.25) < 1e-7, "Mixture, at least one abnormal record"

# Run all tests:
test_patient_risk_score()
