# Mock classes to support tests
class Patient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self._conditions = conditions  # List of condition names
        self._severities = severities  # List of int/float severities

    def get_total_conditions(self):
        return len(self._conditions)

    def get_average_severity(self):
        if not self._severities:
            return 0.0
        return sum(self._severities) / len(self._severities)

class Record:
    def __init__(self, vitals):
        self.vitals = vitals  # dict, e.g., {'bp': ..., 'hr': ...}

    def has_abnormal_vitals(self):
        # Let's say abnormal if systolic BP < 90 or > 140, HR < 50 or > 120.
        if 'bp' in self.vitals:
            bp = self.vitals['bp']
            if bp < 90 or bp > 140:
                return True
        if 'hr' in self.vitals:
            hr = self.vitals['hr']
            if hr < 50 or hr > 120:
                return True
        return False

class Hospital:
    def __init__(self, patients, records):
        self.patients = patients  # dict patient_id -> Patient
        self.records = records    # dict patient_id -> list of Record

    def get_patient(self, patient_id):
        return self.patients.get(patient_id, None)

    def get_recent_records(self, patient_id, days):
        # Ignore days for simplicity, just return all
        return self.records.get(patient_id, [])

# The function signature
def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    if patient is None:
        return 0.0
    score = 0.0
    score += (patient.age / 100) * 30
    score += (patient.get_total_conditions() * 5) * 0.25
    score += (patient.get_average_severity() * 10) * 0.25

    recent_records = hospital.get_recent_records(patient_id, 90)
    has_abnormal = any(r.has_abnormal_vitals() for r in recent_records)
    score += 20 if has_abnormal else 0
    # Clamp to 0-100
    score = max(0.0, min(100.0, float(score)))
    return score


