class Patient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self.conditions = conditions  # list of condition names
        self.severities = severities  # list of severity scores for each condition

    def get_total_conditions(self):
        return len(self.conditions)

    def get_average_severity(self):
        if not self.severities:
            return 0.0
        return sum(self.severities) / len(self.severities)

class Hospital:
    def __init__(self, patients, records):
        self.patients = patients  # dict patient_id -> Patient
        self.records = records  # dict patient_id -> list of records

    def get_patient(self, patient_id):
        return self.patients.get(patient_id)

    def get_recent_records(self, patient_id, days):
        # For testing, just fetch the list assigned for patient
        return self.records.get(patient_id, [])

# Helper to create an 'abnormal' record
def abnormal_record():
    return {'abnormal_vitals': True}
def normal_record():
    return {'abnormal_vitals': False}

# We'll mock the function according to the description for testing purposes.
def patient_risk_score(hospital, patient_id):
    patient = hospital.get_patient(patient_id)
    recent_records = hospital.get_recent_records(patient_id, 90)
    age_score = (patient.age / 100) * 30
    cond_score = (patient.get_total_conditions() * 5) * (25/100)
    sev_score = (patient.get_average_severity() * 10) * (25/100)
    abnormal = any(rec.get('abnormal_vitals', False) for rec in recent_records)
    abn_score = 20 if abnormal else 0
    score = age_score + cond_score + sev_score + abn_score
    return max(0.0, min(score, 100.0))

