# Student 4 enrolls in a missing course (should be skipped)
uni.add_enrollment("stu4", Enrollment("FAKE100", 4.0))
assert calculate_simple_gpa(uni, "stu4") == 0.0, "Course not found is skipped, no credits so GPA is 0.0"

