# Mock classes for testing
class Enrollment:
    def __init__(self, course_code, grade_points):
        self.course_code = course_code
        self._grade_points = grade_points
    def get_grade_points(self):
        return self._grade_points

class Course:
    def __init__(self, code, credits):
        self.code = code
        self.credits = credits

class University:
    def __init__(self, enrollments_dict, courses_dict):
        # enrollments_dict: {student_id: [Enrollment, ...]}
        # courses_dict: {course_code: Course}
        self.enrollments_dict = enrollments_dict
        self.courses_dict = courses_dict
    def get_student_enrollments(self, student_id):
        return self.enrollments_dict.get(student_id, [])
    def get_course(self, course_code):
        return self.courses_dict.get(course_code)

# A testable calculate_simple_gpa implementation (for assert statements to work)
def calculate_simple_gpa(university, student_id):
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0
    total_credits = 0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course and course.credits > 0:
            points = enrollment.get_grade_points() * course.credits
            total_points += points
            total_credits += course.credits
    if total_credits == 0:
        return 0.0
    gpa = total_points / total_credits
    # GPA must be 0.0 to 4.0
    return min(max(gpa, 0.0), 4.0)

