def calculate_simple_gpa(university, student_id):
    '''
    Takes a University object and student_id. For each enrollment university.get_student_enrollments(student_id),
    get the course using university.get_course(enrollment.course_code), multiply enrollment.get_grade_points()
    by course.credits, sum all points and credits, and return total_points / total_credits (0.0-4.0 scale).
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0.0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is None or course.credits == 0:
            continue
        points = enrollment.get_grade_points() * course.credits
        total_points += points
        total_credits += course.credits
    if total_credits == 0.0:
        return 0.0
    return total_points / total_credits

